package cn.kejian.app;import android.content.*;import android.app.*;import org.json.*;import java.time.*;
public class CourseNotificationTest {static int count;static void check(boolean b){if(!b)throw new AssertionError("check "+(count+1));count++;}public static void main(String[] args){Context c=new Context();CourseNotification.reconcile(c);check(c.notifications.cards.isEmpty());check(!c.alarms.scheduled);c.notifications.allowed=false;CourseNotification.configure(c,true,false);check(c.prefs.getBoolean(CourseNotification.ON,false));check(c.notifications.cards.isEmpty()&&!c.alarms.scheduled);c.notifications.allowed=true;CourseNotification.reconcile(c);check(c.notifications.cards.size()==1&&c.alarms.scheduled);Notification n=c.notifications.cards.get(CourseNotification.ID);check(n.visibility==Notification.VISIBILITY_PRIVATE);check(!n.text.contains("UpdatedCourse")&&n.title.equals("课间 · 课程卡片"));check(n.publicVersion.text.equals("解锁后查看课程详情"));check(n.ongoing&&n.silent);check(c.alarms.type==AlarmManager.RTC&&c.alarms.window==600000);for(int i=0;i<10;i++)CourseNotification.configure(c,true,false);check(c.notifications.cards.size()==1);CourseNotification.configure(c,true,true);check(c.notifications.cards.get(CourseNotification.ID).visibility==Notification.VISIBILITY_PUBLIC);CourseNotification.configure(c,false,true);check(c.notifications.cards.isEmpty()&&!c.alarms.scheduled);CourseNotification.configure(c,true,false);check(c.notifications.cards.size()==1&&c.alarms.scheduled);c.notifications.getNotificationChannel(CourseNotification.CHANNEL).importance=0;CourseNotification.reconcile(c);check(c.notifications.cards.isEmpty()&&!c.alarms.scheduled);c.notifications.getNotificationChannel(CourseNotification.CHANNEL).importance=2;String date=LocalDate.now().plusDays(1).toString();JSONObject state=new JSONObject().put("courses",new JSONArray().put(new JSONObject().put("date",date).put("name","UpdatedCourse").put("start","09:00").put("end","10:00")));JSONObject.registry.put("fixture",state);c.prefs.data.put(AlarmScheduler.STATE,"fixture");CourseNotification.configure(c,true,true);check(c.notifications.cards.get(CourseNotification.ID).text.contains("UpdatedCourse"));c.prefs.data.put(AlarmScheduler.STATE,"bad");CourseNotification.reconcile(c);check(c.notifications.cards.isEmpty()&&!c.alarms.scheduled);c.prefs.fail=true;check(!CourseNotification.configure(c,false,false));check(c.prefs.getBoolean(CourseNotification.ON,false));System.out.println(count+" real scheduler checks with mocked Android services passed");}}
